{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "Tetrabenazine, the closest structural analogue (Morgan 0.3731), has a mean absolute oral bioavailability of only 4.9% in patients, directly supporting a low-F outcome for the query's related dimethoxybenzene/basic-amine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Almorexant, which shares the combination of a dimethoxyaryl ring, an amide, and a basic amine, has an absolute oral bioavailability of 11.2% in healthy subjects, supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Donepezil, a dimethoxybenzene CNS drug with a basic amine, has near-complete oral bioavailability (~100%) in humans, providing a high-F counterexample; however, its lower similarity and lack of an amide/lactam reduce transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C15"],
      "claim": "Valbenazine, a tetrabenazine-derived prodrug, has an absolute oral bioavailability of ~49% in humans, above the 20% threshold, but its prodrug ester and lower similarity limit direct transfer to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest analogue tetrabenazine has very low oral bioavailability (4.9%), and almorexant, which combines an amide, basic amine, and dimethoxyaryl system, also has low F (~11%). High-F analogues (donepezil, valbenazine) are less similar and differ in key metabolic/permeability features. The query's low neutral fraction, moderate TPSA, and high rotatable-bond count further support a low-F outcome, so F < 20% is better supported.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for the exact query molecule.",
    "Tetrabenazine lacks the query's lactam and dimethoxyindane side chain, so the metabolic liability may differ.",
    "Donepezil and valbenazine have lower structural similarity and different metabolic/prodrug features.",
    "Transporter effects and metabolic stability of the query are unknown."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "moderate",
      "card_ids": ["C19"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "tetrabenazine"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C33"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "almorexant"
    },
    {
      "applicability": "low",
      "card_ids": ["C24"],
      "decision_effect": "weakened",
      "direction": "contradictory",
      "family": "donepezil"
    },
    {
      "applicability": "low",
      "card_ids": ["C15"],
      "decision_effect": "weakened",
      "direction": "contradictory",
      "family": "valbenazine"
    },
    {
      "applicability": "low",
      "card_ids": ["C29"],
      "decision_effect": "no_change",
      "direction": "neutral_or_unclear",
      "family": "verapamil"
    }
  ],
  "revision_action": "initial"
}

